}

const CustomForm = forwardRef((props, ref) => {
  const [input, setInput] = useState("");

  useImperativeHandle(ref, () => ({
    reset() {
      setInput("");
    }
  }));

  return (
    <input
      value={input}
      onChange={(e) => setInput(e.target.value)}
    />
  );
});

